CREATE TABLE hr_people (id text PRIMARY KEY NOT NULL, first_name text NOT NULL, last_name text NOT NULL, service text NOT NULL DEFAULT '', qr_token text NOT NULL UNIQUE, active integer NOT NULL DEFAULT 1, revision integer NOT NULL DEFAULT 1, created_at text NOT NULL, updated_at text NOT NULL);
CREATE INDEX idx_hr_people_name ON hr_people(last_name, first_name);
CREATE TABLE hr_authorizations (id text PRIMARY KEY NOT NULL, person_id text NOT NULL REFERENCES hr_people(id), kind text NOT NULL, title text NOT NULL, category text NOT NULL DEFAULT '', equipment text NOT NULL DEFAULT '', zone text NOT NULL DEFAULT '', valid_from text NOT NULL, valid_until text NOT NULL DEFAULT '', training_until text NOT NULL DEFAULT '', medical_until text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft', prerequisites_checked integer NOT NULL DEFAULT 0, note text NOT NULL DEFAULT '', revision integer NOT NULL DEFAULT 1, updated_at text NOT NULL, updated_by text NOT NULL);
CREATE INDEX idx_hr_authorizations_person ON hr_authorizations(person_id);
CREATE TABLE hr_authorization_files (id text PRIMARY KEY NOT NULL, authorization_id text NOT NULL REFERENCES hr_authorizations(id), name text NOT NULL, mime text NOT NULL, size integer NOT NULL, sha256 text NOT NULL, author text NOT NULL, created_at text NOT NULL);
CREATE INDEX idx_hr_files_authorization ON hr_authorization_files(authorization_id);
CREATE TABLE hr_authorization_events (id text PRIMARY KEY NOT NULL, person_id text NOT NULL, authorization_id text NOT NULL DEFAULT '', action text NOT NULL, actor_id text NOT NULL, actor text NOT NULL, created_at text NOT NULL);
CREATE INDEX idx_hr_events_person ON hr_authorization_events(person_id,created_at);